from __future__ import annotations
from fractions import Fraction
from typing import Callable, Dict, List, Optional, Sequence, Tuple


def knee_bracket(readings: Dict[int, Fraction], gate: Fraction) -> Dict[str, object]:
    """
    Extract the honest knee information from a finite budget sweep.

    Returns the half-open bracket (last failing grid point, first passing grid
    point], the conservative point estimate (its right endpoint), and whether
    the bracket is a single point (i.e. the grid pinned the knee exactly).
    """
    ks: List[int] = sorted(readings)
    if not ks:
        raise ValueError("empty sweep")
    if any(readings[a] > readings[b] for a, b in zip(ks, ks[1:])):
        raise ValueError("sweep is not monotone in the budget")
    last_fail: Optional[int] = None
    for k in ks:
        if readings[k] < gate:
            last_fail = k
    first_pass: Optional[int] = next((k for k in ks if readings[k] >= gate), None)
    if first_pass is None:
        return {"bracket": (last_fail, None), "estimate": None,
                "identified": False, "note": "gate never met on the grid"}
    lo = 0 if last_fail is None else last_fail + 1
    return {"bracket": (last_fail, first_pass),
            "estimate": first_pass,
            "identified": lo == first_pass,
            "candidates": list(range(lo, first_pass + 1))}


def reopening_margin(readings: Dict[int, Fraction], gate: Fraction) -> Optional[Fraction]:
    """
    Smallest per-cell perturbation that would move the knee to the last failing
    grid point: gate minus that point's reading.
    """
    info = knee_bracket(readings, gate)
    last_fail = info["bracket"][0]
    if last_fail is None:
        return None
    return gate - readings[last_fail]
